def zeta_from_peaks(x1, x2, cycles=1):
    """x1, x2: peak amplitudes ''cycles'' periods apart."""
    delta = np.log(x1 / x2) / cycles          # log decrement per cycle
    return delta / np.sqrt(4 * np.pi**2 + delta**2)   # exact; ~ delta/2pi for light damping

print(zeta_from_peaks(10.0, 8.5))  # ~0.026', NULL, 0);

def transmissibility(r, zeta):
    """r = f / fn. Absolute transmissibility for base excitation."""
    a = (2 * zeta * r) ** 2
    return np.sqrt((1 + a) / ((1 - r**2) ** 2 + a))

r = np.logspace(-1, 1, 400)
T = transmissibility(r, 0.05)', NULL, 1);

BETA = {
    "cantilever": [1.8751, 4.6941, 7.8548],
    "free":       [4.7300, 7.8532, 10.9956],
    "pinned":     [np.pi, 2 * np.pi, 3 * np.pi],
}

def tube_modes(E, rho, L, od, wall, bc="free"):
    """SI units: E [Pa], rho [kg/m3], L, od, wall [m]. Returns Hz."""
    ro, ri = od / 2, od / 2 - wall
    A = np.pi * (ro**2 - ri**2)
    I = np.pi / 4 * (ro**4 - ri**4)
    return [b**2 / (2 * np.pi * L**2) * np.sqrt(E * I / (rho * A)) for b in BETA[bc]]

print(tube_modes(70e9, 2700, 3.0, 0.150, 0.002))', 'Euler–Bernoulli hand check. Ignores shear, payload, joints and propellant.', 2);

def feed_frequency(rho, length, diameter, gas_volume, gas_pressure, gamma=1.4):
    """SI units: rho [kg/m3], length/diameter [m], gas_volume [m3], gas_pressure [Pa]."""
    area = np.pi * diameter**2 / 4
    inertance = rho * length / area            # kg/m^4
    compliance = gas_volume / (gamma * gas_pressure)   # m^3/Pa
    return 1 / (2 * np.pi * np.sqrt(inertance * compliance))

f_feed = feed_frequency(1141, 3.0, 0.040, 0.5e-3, 8e5)
print(f_feed, "Hz")', 'First-cut pogo coincidence check, not a stability analysis.', 3);

def psd_grms(breakpoints):
    """breakpoints: [(f_hz, g2_per_hz), ...] joined by straight lines on log-log axes."""
    area = 0.0
    for (f1, w1), (f2, w2) in zip(breakpoints, breakpoints[1:]):
        m = np.log(w2 / w1) / np.log(f2 / f1)        # log-log slope
        if np.isclose(m, -1):
            area += w1 * f1 * np.log(f2 / f1)
        else:
            area += w1 * f1 / (m + 1) * ((f2 / f1) ** (m + 1) - 1)
    return np.sqrt(area)

def miles(fn, Q, psd_at_fn):
    return np.sqrt(np.pi / 2 * fn * Q * psd_at_fn)

spec = [(20, 0.01), (50, 0.04), (800, 0.04), (2000, 0.01)]
print(psd_grms(spec))', NULL, 4);
from scipy import signal

def srs(t, accel, freqs, Q=10):
    """Absolute-acceleration SRS. t [s] uniform, accel [g], freqs [Hz]."""
    zeta = 1 / (2 * Q)
    out = []
    for fn in freqs:
        w = 2 * np.pi * fn
        sys = signal.lti([2 * zeta * w, w**2], [1, 2 * zeta * w, w**2])
        _, y, _ = signal.lsim(sys, accel, t)
        out.append(np.max(np.abs(y)))
    return np.array(out)

dt = 1e-5
t = np.arange(0, 0.05, dt)
pulse = np.where(t < 1e-3, 100 * np.sin(np.pi * t / 1e-3), 0.0)   # 100 g, 1 ms half-sine
freqs = np.logspace(1, 4, 60)
spectrum = srs(t, pulse, freqs)', 'Pad the record with zeros after the pulse so oscillators finish ringing.', 5);
