from scipy import signal

def alias(f, fs):
    return abs(f - round(f / fs) * fs)

print(alias(9_000, 10_000))   # 1000.0

# Offline low-pass before decimating: 8th-order Butterworth, zero-phase
sos = signal.butter(8, 10_000, btype="low", fs=51_200, output="sos")
y = signal.sosfiltfilt(sos, x)', NULL, 7);

def sensor_chain(peak_g, margin, bw_hz, sens_mv_per_g, bits=16, vfs=5.0):
    need_g = peak_g * margin                  # sensor range must cover this
    fs = 2.56 * bw_hz                         # minimum sample rate
    lsb_g = (2 * vfs / 2**bits) / (sens_mv_per_g / 1000)
    adc_used = need_g * sens_mv_per_g / 1000 / vfs   # fraction of ADC range
    return dict(range_g=need_g, fs_hz=fs, lsb_g=lsb_g, adc_used=adc_used)

print(sensor_chain(120, 1.5, 10_000, 10))

def mount_error(f, f_mounted):
    return 1 / (1 - (f / f_mounted) ** 2) - 1   # lightly damped sensor', NULL, 8);

