INSERT INTO courses (slug, title, subtitle, description, discipline_id, level, instructor_name, instructor_role, updated, hue, position) VALUES ('structures-vibration-dynamic-environments', 'Structures, Vibration and Dynamic Environments', 'From the single-degree-of-freedom oscillator to a flight-ready vibration measurement plan.', 'Learn how launch vehicles and spacecraft shake, how engineers describe and test those loads, and how to measure them without fooling yourself. Hands-on labs let you explore damping, transmissibility, beam modes, pogo, random vibration, shock spectra, aliasing and your own data.', 'structures-vibration', 'Intermediate', 'DUT Space Science Centre', 'Launch & instrumentation team', '2026-11', 150, 0);
INSERT INTO course_also_disciplines (course_slug, discipline_id, position) VALUES ('structures-vibration-dynamic-environments', 'vibration-measurement', 0);
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'outcome', 0, 'Model a structure as SDOF and modal oscillators and compute fn, ζ, Q and transmissibility');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'outcome', 1, 'Estimate beam and axial mode frequencies and judge them against a finite-element model');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'outcome', 2, 'Explain the pogo feedback loop and run a first-cut feed-system frequency check');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'outcome', 3, 'Read and build PSD (Grms) and shock response spectrum specifications');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'outcome', 4, 'Select, mount and wire accelerometers and size a DAQ signal chain without aliasing or clipping');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'outcome', 5, 'Analyse real vibration data and write a defensible measurement plan');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'prerequisite', 0, 'Basic calculus and complex numbers');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'prerequisite', 1, 'Introductory physics (Newton''s laws, springs)');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'prerequisite', 2, 'Signals concepts: sampling and the Fourier transform (helpful, reviewed in module 5)');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'audience', 0, 'Electronics and computing students joining launch-vehicle work');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'audience', 1, 'Postgraduate researchers in propulsion and instrumentation');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('structures-vibration-dynamic-environments', 'audience', 2, 'Engineers preparing test stand or flight measurements');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('structures-vibration-dynamic-environments', 'm1', 'Vibration fundamentals', 'The single-degree-of-freedom oscillator: the one model that explains most of what you will measure.', 0);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 'm1', 'Why rockets shake: sources and consequences', 15, 'Where launch vibration comes from, what it breaks, and why we both design for it and measure it.', 0);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 0, '5Fd5KTETYeo', 'Why you shake a satellite before launch', 'Per Aspera Ad Astra 31', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 0, 'p', '{"text":"A launch vehicle is a long, light, flexible structure carrying a violent energy source. Everything on board, from the engine mounts to a flight computer to a CubeSat, sees that energy as **mechanical motion**: steady acceleration, vibration, shock and acoustic pressure. This course is about understanding that motion well enough to design for it, test for it and measure it."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 1, 'h', '{"text":"Four families of dynamic load"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 2, 'table', '{"head":["Family","Typical source","Frequency character","Time character"],"rows":[["Quasi-static","Thrust, drag, gravity, manoeuvres","0–a few Hz","Seconds to minutes"],["Low-frequency transient / sine-like","Ignition, liftoff release, gusts, staging, engine cut-off, pogo","Roughly 5–100 Hz","Milliseconds to seconds; pogo is sustained"],["Random vibration and acoustics","Engine combustion noise, turbulent boundary layer, jet noise reflected from the pad","20 Hz–2 kHz (up to 10 kHz in acoustics)","Continuous, statistical"],["Shock","Pyrotechnic separation, valve actuation, latch release, impact","100 Hz–10 kHz+","Microseconds to a few ms"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 3, 'h', '{"text":"What goes wrong"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 4, 'ul', '{"items":["**Overstress:** a load exceeds the strength of a bracket, tank skirt, weld or fastener.","**Fatigue:** many small cycles crack a part that survived any single cycle.","**Functional failure:** a relay chatters, a connector unseats, a gyro saturates, a crystal oscillator jumps frequency.","**Resonant amplification:** a part sitting on its natural frequency sees far more motion than the structure it is mounted on. The size of that amplification is the subject of the next three lessons.","**Unstable coupling:** the structure and the propulsion system exchange energy and the oscillation grows (pogo)."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 5, 'callout', '{"kind":"key","title":"The core idea","text":"Almost every vibration problem has three parts: a **source** (what excites), a **path** (the structure between source and component) and a **receiver** (the component that must survive or the sensor that must record). Your job is usually to find the weakest link among the three."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 6, 'h', '{"text":"Design, test and measure form a loop"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 7, 'p', '{"text":"Analysis predicts the environment. Ground tests (shaker, acoustic chamber, shock rig) verify hardware against it with margin. Flight and static-fire **measurements** close the loop by showing what the environment really was. Measurements are only useful if the sensor, mounting, sampling and filtering are right, which is why the last module of this course spends so long on them."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 0, 'Launch loads come in four families: quasi-static, low-frequency transient, random/acoustic, and shock.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 1, 'Resonance, fatigue and unstable coupling are the main ways vibration hurts hardware.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 2, 'Think source, path, receiver. Design, test and measurement form one loop.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'why-rockets-shake', 0, 'NASA-HDBK-7005 Dynamic Environmental Criteria', 'NASA', 'https://ntrs.nasa.gov/search?q=NASA-HDBK-7005', 'Also in the team library (.archive/material #10)');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 'm1', 'The single-degree-of-freedom oscillator', 30, 'Mass, spring and damper: equation of motion, natural frequency and what the solution looks like.', 1);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 0, '9_d8CQrCYUw', '19. Introduction to Mechanical Vibration', 'MIT OpenCourseWare', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 0, 'p', '{"text":"Strip a structure down to one lumped mass **m** on a spring of stiffness **k** with a viscous damper **c**, free to move in one direction, and you get the model that underlies accelerometers, isolators, shock spectra and the first mode of a rocket stack."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 1, 'eq', '{"text":"m\\ddot{x} + c\\dot{x} + kx = F(t)","name":"Equation of motion","caption":"Equation of motion (Newton''s second law)"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 2, 'h', '{"text":"The two numbers that describe it"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 3, 'eq', '{"text":"\\omega_n = \\sqrt{k/m} \\qquad f_n = \\frac{\\omega_n}{2\\pi} \\qquad \\zeta = \\frac{c}{2\\sqrt{km}}","name":"Natural frequency and damping","caption":"Natural frequency and damping ratio"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 4, 'ul', '{"items":["**fn** (Hz) is the frequency at which the system rings if you disturb it and let go. Stiffer or lighter means higher.","**ζ** (zeta) is the damping ratio. 0 means no damping; 1 is critical damping, the point where oscillation just disappears. Metal structures typically have ζ of about 0.005–0.05; rubber isolators far more."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 5, 'h', '{"text":"Free response (underdamped, ζ < 1)"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 6, 'eq', '{"text":"x(t) = A\\,e^{-\\zeta\\omega_n t}\\cos(\\omega_d t - \\varphi) \\qquad \\omega_d = \\omega_n\\sqrt{1-\\zeta^2}","name":"Free decay response","caption":"Decaying oscillation at the damped natural frequency"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 7, 'p', '{"text":"For small damping ωd is almost equal to ωn, so damping barely changes the ringing frequency. It changes how fast the ringing dies."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 8, 'callout', '{"kind":"tip","title":"Units sanity check","text":"A 1 kg mass on a 1 kN/m spring has $\\omega_n = \\sqrt{1000} \\approx 31.6$ rad/s, so $f_n \\approx 5.03$ Hz. Quadrupling the mass halves the frequency. Use this as a quick mental estimate whenever someone quotes a mount frequency."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 9, 'h', '{"text":"Try it"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 10, 'p', '{"text":"The lab below plots the free response. Change **fn** and **ζ** and watch both the ringing frequency and the decay envelope."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 11, 'lab', '{"id":"free-decay"}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 0, 'One mass, one spring and one damper give fn = √(k/m)/2π and ζ = c/(2√(km)).');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 1, 'Real structures are lightly damped (ζ ≈ 0.5–5%), so they ring near fn for many cycles.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 2, 'Damping barely moves the ringing frequency; it controls how fast the ringing decays.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'sdof-oscillator', 0, 'MIT 2.003SC: Introduction to Mechanical Vibration (Lecture 19)', 'MIT OpenCourseWare', 'https://ocw.mit.edu/courses/2-003sc-engineering-dynamics-fall-2011/resources/lecture-19-introduction-to-mechanical-vibration/', NULL);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 'm1', 'Damping, Q factor and measuring them', 25, 'Logarithmic decrement, half-power bandwidth, and why Q is the number that tells you how bad resonance will be.', 2);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 0, 'wzEqF_UQkks', '20. Linear System Modeling a Single Degree of Freedom Oscillator', 'MIT OpenCourseWare', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 0, 'p', '{"text":"You cannot compute damping from geometry, so you measure it. There are two standard ways, one in the time domain and one in the frequency domain."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 1, 'h', '{"text":"1. Logarithmic decrement (time domain)"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 2, 'p', '{"text":"Take two successive peaks of a free decay, x₁ and x₂ one period apart:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 3, 'eq', '{"text":"\\delta = \\ln\\frac{x_1}{x_2} = \\frac{2\\pi\\zeta}{\\sqrt{1-\\zeta^2}} \\approx 2\\pi\\zeta","name":"Logarithmic decrement","caption":"Small-damping approximation is good for ζ < 0.1"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 4, 'p', '{"text":"Rule of thumb: the amplitude halves in about 0.11/ζ cycles, so ζ = 1% halves in roughly 11 cycles."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 5, 'h', '{"text":"2. Half-power bandwidth (frequency domain)"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 6, 'p', '{"text":"Sweep a sinusoid through resonance and find the two frequencies f₁ and f₂ where the response is 1/√2 (−3 dB) of the peak:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 7, 'eq', '{"text":"Q = \\frac{f_n}{f_2 - f_1} \\approx \\frac{1}{2\\zeta}","name":"Quality factor","caption":"Quality factor"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 8, 'callout', '{"kind":"key","title":"Why Q matters","text":"At resonance, a lightly damped system amplifies its input by about **Q**. A bracket with ζ = 2% has Q ≈ 25. A 1 g input at its natural frequency becomes about 25 g at the component. Test engineers quote **Q = 10** as a conservative default when damping is unknown."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 9, 'table', '{"head":["Structure","Typical ζ","Typical Q"],"rows":[["Welded steel / aluminium frame","0.005 – 0.02","25 – 100"],["Bolted joints, avionics box","0.02 – 0.05","10 – 25"],["Composite panel","0.01 – 0.03","17 – 50"],["Elastomer isolator","0.1 – 0.3","1.7 – 5"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 10, 'p', '{"text":"These are illustrative ranges. Damping depends strongly on amplitude, joints and temperature, which is exactly why it must be measured on the real hardware."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 11, 'callout', '{"kind":"tip","title":"Practice","text":"In the lab above, set ζ = 0.02 and estimate δ from two successive peaks. Compare with 2πζ."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 0, 'Log decrement: δ = ln(x₁/x₂) ≈ 2πζ. Half-power: Q = fn/Δf ≈ 1/(2ζ).');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 1, 'Resonant amplification is about Q, so lightly damped parts amplify by 10× to 100×.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'damping-and-q', 2, 'Damping must be measured on real hardware; handbook values are only a starting point.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 'm1', 'Forced response, transmissibility and isolation', 35, 'How a base-driven oscillator responds across frequency, and when an isolator helps or hurts.', 3);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 0, 'f1pxiNDTyHc', '21. Vibration Isolation', 'MIT OpenCourseWare', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 0, 'p', '{"text":"Most spacecraft problems are **base excitation**: the mounting surface moves and the component responds. Let $r = f / f_n$ be the ratio of the driving frequency to the natural frequency. The ratio of response amplitude to base amplitude is the **transmissibility**:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 1, 'eq', '{"text":"T(r) = \\sqrt{\\frac{1 + (2\\zeta r)^2}{(1-r^2)^2 + (2\\zeta r)^2}}","name":"Transmissibility","caption":"Absolute transmissibility for base excitation"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 2, 'h', '{"text":"Three regions"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 3, 'ul', '{"items":["**Below resonance** ($r \\ll 1$): $T \\approx 1$. The part moves rigidly with its base.","**At resonance** ($r \\approx 1$): $T$ peaks at about $Q$. This is where hardware gets damaged.","**Isolation region** ($r > \\sqrt{2} \\approx 1.41$): $T < 1$. The mass barely moves while the base shakes. Above this, a softer mount is better; damping now slightly *worsens* high-frequency isolation."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 4, 'lab', '{"id":"transmissibility"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 5, 'callout', '{"kind":"warn","title":"The designer''s trade","text":"More damping lowers the resonant peak but raises transmissibility above √2·fn. Isolating avionics from engine vibration means putting fn well below the lowest troublesome input frequency and accepting the unavoidable low-frequency resonance. You must then check the stack still survives the *low-frequency* loads, for example, liftoff transients, with the soft mount''s larger deflection."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 6, 'h', '{"text":"Accelerometers are isolators too"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 7, 'p', '{"text":"An accelerometer is a tiny SDOF system whose output is the relative motion of its seismic mass. It reports acceleration faithfully only for r well below 1, which is the same curve read in reverse. Lesson 5.2 uses this to explain mounting limits."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 0, 'Transmissibility is ≈1 below fn, ≈Q at fn, and <1 only above √2·fn.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 1, 'Isolators trade a low-frequency resonance for high-frequency attenuation; damping helps the peak but hurts attenuation.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'forced-response-isolation', 2, 'An accelerometer is an SDOF system used well below its own resonance.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm1', 0, 'A 4 kg mass sits on a spring of stiffness 4 000 N/m. What is its natural frequency?', '["≈ 1.6 Hz","≈ 5.0 Hz","≈ 31.6 Hz","≈ 100 Hz"]', 1, 'ωn = √(k/m) = √1000 = 31.6 rad/s, so fn = 31.6 / 2π ≈ 5.03 Hz.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm1', 1, 'Doubling the mass while keeping the stiffness the same changes fn by which factor?', '["×2","×√2","×1/√2","×1/2"]', 2, 'fn ∝ √(k/m). Doubling m divides fn by √2.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm1', 2, 'Two successive free-decay peaks are 10.0 mm and 8.5 mm. What is the damping ratio ζ approximately?', '["0.026","0.16","0.0026","0.5"]', 0, 'δ = ln(10/8.5) = 0.1625, and ζ ≈ δ/2π = 0.026.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm1', 3, 'A structure has ζ = 0.025. Its resonant amplification Q is about:', '["2.5","10","20","40"]', 2, 'Q ≈ 1/(2ζ) = 1/0.05 = 20.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm1', 4, 'For base excitation, above what frequency ratio r = f/fn does an isolator begin to attenuate?', '["r > 0.5","r > 1","r > √2","r > 2"]', 2, 'T(r) falls below 1 once r > √2, regardless of the damping ratio.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm1', 5, 'Increasing damping in an isolator will usually…', '["Lower the resonant peak and lower high-frequency transmissibility","Lower the resonant peak but raise high-frequency transmissibility","Raise both","Have no effect on transmissibility"]', 1, 'Damping trades resonant peak for worse attenuation above √2·fn.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('structures-vibration-dynamic-environments', 'm2', 'From one mass to a rocket', 'Modes, mode shapes and beam models: how a real vehicle is built out of many oscillators.', 1);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 'm2', 'Natural frequencies and mode shapes', 30, 'Two masses, two frequencies. The eigenproblem that scales to a whole finite-element model.', 0);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 0, '9CPA6WG6mRo', '22. Finding Natural Frequencies & Mode Shapes of a 2 DOF System', 'MIT OpenCourseWare', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 0, 'p', '{"text":"Add a second mass and the system has **two** natural frequencies, each with a characteristic pattern of motion called a **mode shape**. In matrix form, with mass matrix **M** and stiffness matrix **K**:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 1, 'eq', '{"text":"M\\ddot{\\mathbf{x}} + K\\mathbf{x} = 0 \\;\\Rightarrow\\; (K - \\omega^2 M)\\,\\boldsymbol{\\varphi} = 0 \\;\\Rightarrow\\; \\det(K - \\omega^2 M) = 0","name":"Eigenproblem","caption":"Undamped free vibration and the eigenproblem"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 2, 'ul', '{"items":["Each root ω² gives a **natural frequency**.","Each corresponding vector φ is a **mode shape**: the relative displacement of each mass when the system vibrates at that frequency.","An N-degree-of-freedom model has N modes. A finite-element model of a rocket may have hundreds, but only the lowest handful matter for loads and control."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 3, 'h', '{"text":"Worked example"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 4, 'p', '{"text":"Two equal masses m joined to a wall and to each other by identical springs k (wall–k–m–k–m). Then:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 5, 'eq', '{"text":"\\omega_1^2 = \\frac{3-\\sqrt5}{2}\\frac{k}{m} \\approx 0.382\\,\\frac{k}{m} \\qquad \\omega_2^2 = \\frac{3+\\sqrt5}{2}\\frac{k}{m} \\approx 2.618\\,\\frac{k}{m}","name":"Two-mass frequencies","caption":"Mode 1: masses move in phase, mode 2: out of phase (ratio 1 : −0.618)"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 6, 'p', '{"text":"The second frequency is √(2.618/0.382) ≈ 2.6 times the first. In long slender structures, modes are spread like this, not bunched, which is why the first bending mode often controls the design."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 7, 'callout', '{"kind":"key","title":"Mode shape intuition","text":"A mode shape tells you **where to put (and where not to put) a sensor or an actuator**. A node (point of zero motion) in mode 1 will not see mode 1. A sensor placed there is blind to that mode."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 0, 'Natural frequencies are eigenvalues of (K, M); mode shapes are the eigenvectors.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 1, 'A model with N degrees of freedom has N modes; usually only the lowest few matter.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 2, 'Mode shapes tell you where sensors will or will not see a mode.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'modes-two-dof', 0, 'MIT 2.003SC Lecture 22', 'MIT OpenCourseWare', 'https://ocw.mit.edu/courses/2-003sc-engineering-dynamics-fall-2011/resources/lecture-22-finding-natural-frequencies/', NULL);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 'm2', 'Modal analysis and superposition', 35, 'Why modes make big problems easy: orthogonality, modal coordinates and effective mass.', 1);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 0, 'tm51lwadMOc', '23. Vibration by Mode Superposition', 'MIT OpenCourseWare', NULL);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 1, 'OxcCPTc_bXw', '24. Modal Analysis: Orthogonality, Mass Stiffness, Damping Matrix', 'MIT OpenCourseWare', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 0, 'p', '{"text":"Mode shapes have a remarkable property: they are **orthogonal** with respect to M and K. Changing coordinates from physical displacements to **modal coordinates** q (x = Φ·q) turns the N coupled equations into N *independent* SDOF equations:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 1, 'eq', '{"text":"\\ddot{q}_i + 2\\zeta_i\\omega_i\\dot{q}_i + \\omega_i^2 q_i = \\Gamma_i\\, a_{\\text{base}}(t)","name":"Modal equation","caption":"Modal equation: one SDOF oscillator per mode, driven by a participation factor Γᵢ"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 2, 'p', '{"text":"This is why everything you learned in module 1 applies to a whole structure: **a structure is a sum of SDOF oscillators**, each with its own fn, ζ and share of the response."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 3, 'h', '{"text":"Modal mass and effective modal mass"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 4, 'ul', '{"items":["**Modal mass** depends on how the mode shape is normalised, so it is not unique.","**Effective modal mass** is the part of the *total* mass that actually moves in a given mode for a given excitation direction. The effective masses of all modes sum to the total mass.","A common screening rule is to keep enough modes that their effective masses add up to 90% or more of the total in each excitation direction."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 5, 'callout', '{"kind":"tip","title":"How this is used","text":"A launch-vehicle loads analysis combines a small number of modes (a *coupled loads analysis*, CLA) with the launch-vehicle forcing. The payload''s first modes should be above the launcher''s minimum requirement, so that the payload does not couple with the vehicle''s own modes. Small-satellite and CubeSat specs set minimum frequencies for this reason."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 6, 'h', '{"text":"Modal damping"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 7, 'p', '{"text":"Damping is almost always applied per mode (a single ζ per mode), not as a physical damper matrix, because we know modal damping from tests and cannot derive it from geometry."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 0, 'Orthogonal modes decouple the equations: a structure acts as a sum of SDOF oscillators.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 1, 'Effective modal mass says how much mass participates in each mode; aim for ≥ 90% captured.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'modal-superposition', 2, 'Damping is applied per mode, with values from test, not from geometry.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'beams', 'm2', 'Beams and rods: continuous structures', 30, 'Closed-form frequencies for bending and axial modes, the first sanity check on any FE model.', 2);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'beams', 0, '1xJJu5p3dD0', '27. Vibration of Continuous Structures: Strings, Beams, Rods, etc.', 'MIT OpenCourseWare', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'beams', 0, 'p', '{"text":"A uniform beam has infinitely many modes. Closed-form solutions exist for simple boundary conditions and they make excellent hand checks on finite-element results."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'beams', 1, 'eq', '{"text":"f_n = \\frac{(\\beta_n L)^2}{2\\pi L^2}\\sqrt{\\frac{EI}{\\rho A}}","name":"Beam bending frequency","caption":"Euler–Bernoulli bending frequency. E modulus, I second moment of area, ρ density, A area"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'beams', 2, 'table', '{"head":["Boundary condition","β₁L","β₂L","β₃L"],"rows":[["Cantilever (fixed–free)","1.875","4.694","7.855"],["Free–free (rocket in flight)","4.730","7.853","10.996"],["Pinned–pinned","π","2π","3π"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'beams', 3, 'p', '{"text":"For axial (longitudinal) vibration of a fixed–free rod the frequencies are fn = (2n − 1)/(4L) · √(E/ρ). The √(E/ρ) is the speed of sound in the material (about 5 100 m/s in aluminium and 5 000 m/s in steel)."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'beams', 4, 'lab', '{"id":"beam-modes"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'beams', 5, 'callout', '{"kind":"warn","title":"Limits of the formulas","text":"These assume a uniform, slender beam. They overestimate frequency for short, deep sections (shear deformation), and the real vehicle has non-uniform mass, tanks full of sloshing propellant and joints that are softer than the parent material. Use them to catch gross errors, not as final numbers."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'beams', 0, 'Bending fn ∝ (1/L²)·√(EI/ρA). Halving the length raises fn four-fold.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'beams', 1, 'Free–free beam constants (4.73, 7.85, 11.0) describe a vehicle in flight; cantilever (1.875…) is a fixed test setup.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'beams', 2, 'Closed-form beam frequencies are hand checks for finite-element results, not replacements.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 'm2', 'The launch vehicle as a dynamic structure', 25, 'Axial, lateral and torsional modes, the free-free vehicle, and why the first axial mode matters for pogo.', 3);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 0, 'p', '{"text":"A launch vehicle is nearly a free-free beam in flight, with a changing mass: propellant burns off, so mode frequencies **rise** during flight. Analysts check the vehicle at several flight times, typically liftoff, max-q and burnout."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 1, 'table', '{"head":["Mode family","Motion","Why it matters"],"rows":[["Axial (longitudinal)","Stack compresses and stretches along the thrust axis","Couples with the propulsion feed system: the root cause of pogo. Excited by thrust transients"],["Lateral (bending)","Bends side to side, like a diving board","Couples with guidance and control (control-structure interaction) and gust loads"],["Torsional","Twists about the long axis","Roll control and fin flutter in sounding rockets"],["Propellant slosh","Liquid surface sloshes in tanks","Low-frequency (≈0.5–2 Hz) coupling with control; handled with baffles"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 2, 'callout', '{"kind":"key","title":"Typical scale","text":"Large launch vehicles have first axial modes in the single to low tens of Hz. A small sounding rocket or a small liquid-propellant vehicle can be much higher because it is shorter and stiffer relative to its mass. Do not assume a number: **compute or measure it** for the vehicle you are working on."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 3, 'h', '{"text":"Load paths"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 4, 'p', '{"text":"Thrust enters the vehicle at the engine mount, travels up the thrust structure into the tanks or interstage, and out to the payload. Every joint on that path is a spring in series. Joints are usually the dominant source of both **flexibility** and **damping**, and they are the least well predicted part of the model, which is why modal testing exists."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 5, 'h', '{"text":"Reading list for this module"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 6, 'ul', '{"items":["Chowdhury 2012 (UKZN): sounding-rocket flight dynamics.","Williams 2020 (UKZN): composite oxidiser tank structures.","NASA SP-8055, discussed in module 3."]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 0, 'In flight a vehicle is close to free–free, and its modes rise as propellant burns off.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 1, 'Axial modes couple with the feed system (pogo); bending couples with control; torsion with roll and fins.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 2, 'Joints dominate flexibility and damping, so model predictions need test verification.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 0, 'Chowdhury 2012: Sounding rocket flight dynamics', 'UKZN ASRI thesis', NULL, 'Team library: .archive/material/ukzn_asri_theses');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'vehicle-as-structure', 1, 'Williams 2020: Composite oxidiser tank', 'UKZN ASRI thesis', NULL, 'Team library: .archive/material/ukzn_asri_theses');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm2', 0, 'In modal analysis, what does orthogonality of the mode shapes allow?', '["It makes all modes have the same frequency","It decouples the equations into independent SDOF equations","It removes damping from the model","It guarantees the structure is stable"]', 1, 'Orthogonality with respect to M and K diagonalises the system into independent modal oscillators.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm2', 1, 'Effective modal mass is useful because…', '["It always equals total mass","It shows how much mass participates in each mode, and you check that the modes kept capture most (≥ 90%) of it","It gives damping","It gives the mode''s frequency"]', 1, 'Effective masses sum to total mass; the cumulative fraction guides how many modes to keep.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm2', 2, 'A free–free uniform beam''s first bending constant β₁L is about:', '["1.875","3.142","4.730","7.855"]', 2, 'Free–free: 4.730. Cantilever: 1.875. Pinned–pinned: π.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm2', 3, 'If a uniform cantilever''s length is halved (everything else equal), its first bending frequency becomes…', '["2×","4×","√2×","Unchanged"]', 1, 'fn ∝ 1/L², so halving L gives 4× the frequency.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm2', 4, 'As propellant burns off during flight, a vehicle''s natural frequencies generally…', '["Fall","Rise","Stay constant","Randomly vary"]', 1, 'Mass falls while stiffness is nearly unchanged, so frequencies rise.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm2', 5, 'Which mode family is most closely tied to pogo?', '["First lateral bending","Torsion","Propellant slosh","First axial (longitudinal)"]', 3, 'Pogo is a coupling between the structure''s axial mode and the propulsion feed system.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('structures-vibration-dynamic-environments', 'm3', 'Transient loads and pogo', 'Thrust-driven events and the one instability that couples the vehicle structure to its own engines.', 2);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 'm3', 'Transient loads from thrust excitation', 25, 'Ignition, liftoff, cut-off and staging: short events that ring the whole vehicle.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 0, 'p', '{"text":"A transient is a disturbance that begins and ends: the structure responds, then rings down. For a rocket the dominant transients come from the **thrust history** itself."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 1, 'table', '{"head":["Event","What changes","Typical response"],"rows":[["Ignition / thrust build-up","Thrust rises from zero in tens of ms to seconds","Axial and lateral ringing of the stack; pad hold-down loads"],["Liftoff / hold-down release","Stored preload released at once","Large axial spring-back (the ''liftoff transient'')"],["Engine cut-off","Thrust drops quickly, ''thrust decay''","Structure rings at its axial frequencies; payload sees sine-like burst"],["Staging and separation","Stage load removed, pyrotechnic firing","Axial transient plus a shock environment (module 4)"],["Gust and wind shear","Aerodynamic side loads","Lateral bending, controlled by the autopilot"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 2, 'h', '{"text":"How fast is ''fast''? The ratio that decides everything"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 3, 'p', '{"text":"Compare the **rise (or decay) time** tr of the thrust with the **period** T of the structural mode (T = 1/fn):"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 4, 'ul', '{"items":["**tr ≫ T** (slow change): the structure follows quasi-statically. The dynamic load is only the static load.","**tr ≈ T/2 or shorter**: strong dynamic excitation. For an abrupt step the peak response is up to **2×** the static load (the classic dynamic load factor for an undamped SDOF).","**tr ≪ T:** an impulse-like load. Response depends on the impulse, not the peak force."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 5, 'callout', '{"kind":"key","title":"Dynamic load factor","text":"A force that suddenly steps from 0 to F on an undamped SDOF system drives a peak displacement of 2F/k, twice the static F/k. Damping reduces the overshoot; a smooth ramp of rise time ≥ ~2–3 periods practically removes it."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 6, 'p', '{"text":"That is why engine start-up sequences, valve opening rates and soft-release hold-downs are partly **vibration design**: slowing the thrust build-up trades performance for lower dynamic loads."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 7, 'h', '{"text":"How this is analysed"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 8, 'ul', '{"items":["Model the thrust-time curve as a force at the engine mounts.","Solve the transient response with modal superposition (module 2), keeping low modes.","Report peak accelerations and interface loads at the payload and critical joints; compare with design criteria."]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 0, 'Transients come from thrust build-up, release, cut-off and staging.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 1, 'Compare thrust rise/decay time with the structural period; fast events give dynamic overshoot up to 2×.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 2, 'Thrust ramp rate is a design variable, not just a performance one.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'thrust-transients', 0, 'NASA Space Vehicle Design Criteria: Transient Loads from Thrust Excitation', 'NASA', 'https://ntrs.nasa.gov/search?q=Transient%20Loads%20from%20Thrust%20Excitation', 'Also in the team library (.archive/material #09)');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 'm3', 'Pogo: the structure–propulsion feedback loop', 30, 'How a longitudinal vibration, a feed line and a thrust chamber can form a self-excited oscillator.', 1);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 0, '9h14NtlChy4', 'Apollo 6''s Moon Rocket Bounced. Part of the Fix Was Helium', 'Postflight', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 0, 'p', '{"text":"Pogo is an instability in which the vehicle''s **axial structural vibration** and the **propulsion system''s pressure and flow oscillations** feed each other. It is named for the pogo stick: the vehicle bounces along its long axis."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 1, 'h', '{"text":"The loop"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 2, 'ol', '{"items":["The structure flexes axially at its natural frequency, moving the engine and the tanks.","That motion changes the pressure at the **pump/engine inlet** and the flow through the feed line.","Changing inlet pressure changes **chamber pressure and thrust**. The engine acts as a gain.","The thrust oscillation pushes on the structure at that same frequency, reinforcing step 1."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 3, 'callout', '{"kind":"key","title":"Why it is called an instability","text":"If energy fed back by the propulsion system exceeds the structure''s own damping at that frequency, the amplitude **grows** (it is self-excited). It has no external driver and can reach damaging levels within seconds."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 4, 'h', '{"text":"What makes it likely"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 5, 'ul', '{"items":["**Frequency coincidence:** the feed-system hydraulic frequency is near an axial structural mode (and a mode of that propellant column).","**High gain:** sensitive engine thrust to inlet pressure, for example, with pump cavitation.","**Low damping** in the structural mode.","Long, compliant feed lines or gas ullage with little isolation."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 6, 'h', '{"text":"Historical context"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 7, 'p', '{"text":"Pogo appeared on early Saturn V flights: Apollo 6 (1968) saw strong oscillation, and a suppression system was introduced for later missions, with helium used to create a compressible volume (an *accumulator*) in the feed system. On Apollo 13 the centre engine shut off early partly because of pogo. See the video and the NASA references for the full story."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 8, 'callout', '{"kind":"warn","title":"Relevance to pressure-fed engines","text":"Pump-fed engines are generally more susceptible because pumps and cavitation add gain and compliance. Pressure-fed and blowdown systems (like many small test engines) usually have lower risk, but long feed lines, light structures or compliant tanks can still produce coupled instability. Do the check; do not assume immunity."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 0, 'Pogo = structure''s axial mode ↔ feed system ↔ thrust, a closed feedback loop.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 1, 'It grows when fed-back energy exceeds structural damping; frequency coincidence makes it worse.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 2, 'Pump-fed engines are more susceptible, but pressure-fed systems should still be checked.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'pogo-mechanism', 0, 'NASA SP-8055 Prevention of Coupled Structure-Propulsion Instability (Pogo)', 'NASA', 'https://ntrs.nasa.gov/search?q=Prevention%20of%20Coupled%20Structure-Propulsion%20Instability%20Pogo', 'Also in the team library (.archive/material #06)');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 'm3', 'Pogo stability and suppression', 30, 'A simple feed-system model, the frequency-separation rule of thumb, and how accumulators detune the loop.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 0, 'p', '{"text":"A first-cut check treats the feed line as a mass–spring system. The **inertance** of the liquid in the line acts as the mass; the **compliance** of a gas volume (accumulator, cavitation or ullage) acts as the spring."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 1, 'eq', '{"text":"I = \\frac{\\rho L}{A} \\qquad C = \\frac{V}{\\gamma p} \\qquad f_{\\text{feed}} = \\frac{1}{2\\pi\\sqrt{IC}}","name":"Feed-line frequency","caption":"Inertance, gas compliance and the hydraulic natural frequency"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 2, 'ul', '{"items":["**ρ·L/A**: liquid density × line length ÷ flow area. A long, thin line has a large inertance.","**V/(γp)**: gas volume ÷ (heat-capacity ratio × pressure). More gas or lower pressure gives a softer ''spring''."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 3, 'h', '{"text":"Two ways to design pogo out"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 4, 'ol', '{"items":["**Detune.** Move f_feed away from the structure''s axial frequency. Add compliance (lower f_feed) or stiffen the line/shorten it (higher f_feed). Typical practice is to separate them by a safe margin, not merely avoid exact equality.","**Add damping.** A gas-charged accumulator on the feed line also absorbs pressure oscillations. Other approaches include orifices and active control. NASA SP-8055 lists the criteria and options."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 5, 'lab', '{"id":"pogo"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 6, 'callout', '{"kind":"warn","title":"Educational model only","text":"Real pogo analysis uses a full multi-mode structure, pump and engine transfer functions and closed-loop stability margins. The lab shows why frequency coincidence matters and how an accumulator moves the feed-system frequency. It does **not** replace SP-8055-style analysis."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 7, 'h', '{"text":"What to measure"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 8, 'ul', '{"items":["Longitudinal acceleration (accelerometer on the engine thrust frame and near the payload) in the 5–100 Hz band.","Inlet and chamber pressure with a **dynamic** (piezo) pressure transducer, plus thrust if the stand allows.","Spectrogram: look for a narrow, growing line that tracks the axial mode as propellant depletes.","Sample at ≥ 1 kHz with anti-alias filtering, since pressure and acceleration must be time-aligned."]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 0, 'f_feed = 1/(2π√(I·C)), with I = ρL/A and C = V/(γp), is a useful first check.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 1, 'Fix pogo by detuning f_feed from the structural mode and/or adding damping (accumulators).');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-suppression', 2, 'Measure axial acceleration and dynamic pressure together and look for a growing spectral line.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 'm3', 'Pogo, chugging and combustion instability', 20, 'Three oscillation phenomena that are often confused. Frequency band tells you which one you have.', 3);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 0, 'p', '{"text":"Rocket engines can oscillate in several ways. Which is which? Frequency and coupling partner are the first clues."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 1, 'table', '{"head":["Phenomenon","Approx. band","Coupled with","Typical remedy"],"rows":[["Pogo","≈ 5–60 Hz","Vehicle structure ↔ feed system ↔ engine","Detune, accumulators, damping (SP-8055)"],["Chugging (low-frequency combustion instability)","≈ 10–400 Hz","Feed system ↔ combustion chamber (not the vehicle structure)","Raise injector pressure drop, change feed-line dynamics"],["Intermediate / screech (high-frequency)","≈ 1–10 kHz and above","Acoustic modes of the chamber","Baffles, acoustic cavities, injector changes (SP-8113)"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 2, 'p', '{"text":"Band edges overlap and differ between sources. Treat them as a rough guide only."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 3, 'callout', '{"kind":"tip","title":"The practical test","text":"If the oscillation frequency **tracks the vehicle''s structural mode** as it changes (e.g. with propellant depletion), suspect pogo. If it stays at a fixed feed-system or chamber frequency regardless of the structure, suspect combustion or feed-system instability. A rigid test stand removes the structure from the loop, so pogo cannot appear on a stiff stand while it can in flight."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 4, 'h', '{"text":"Why this matters for measurement"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 5, 'ul', '{"items":["Pogo needs only **modest bandwidth** (to ~100 Hz) but long records so the growth envelope is visible.","Screech needs **high-bandwidth** pressure sensing (≥ 20 kHz) with a sampling rate to match, and the right sensor mounting (flush, cooled).","Both need synchronous channels so phase between pressure and acceleration can be computed."]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 0, 'Pogo (≈5–60 Hz) couples with the vehicle structure; chugging couples feed system and chamber; screech is acoustic.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 1, 'Frequency that tracks the structure points to pogo.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 2, 'Different instabilities need different sensors, bandwidths and record lengths.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'pogo-vs-combustion', 0, 'NASA SP-8113 Liquid Rocket Engine Combustion Stabilization Devices', 'NASA', 'https://ntrs.nasa.gov/search?q=Liquid%20Rocket%20Engine%20Combustion%20Stabilization%20Devices', 'Also in the team library (.archive/material #07)');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm3', 0, 'A force steps instantly from 0 to F on an undamped SDOF system. The peak displacement is…', '["F/k","1.5 F/k","2 F/k","4 F/k"]', 2, 'The classic dynamic load factor for a step is 2.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm3', 1, 'Thrust rises over a time much longer than the structure''s period. The dynamic effect is…', '["Large overshoot","Quasi-static: little dynamic amplification","Impulsive","Resonant"]', 1, 'A slow ramp lets the structure follow the load statically.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm3', 2, 'Which is NOT part of the pogo feedback loop?', '["Axial structural vibration","Inlet pressure and flow oscillation","Thrust oscillation","Magnetic field of the launch pad"]', 3, 'Pogo is a structure–feed system–thrust loop.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm3', 3, 'Pogo grows when…', '["Fed-back energy exceeds structural damping at that frequency","Thrust is exactly constant","The vehicle is perfectly rigid","The accumulator is full of liquid"]', 0, 'It is self-excited; growth means gain exceeds damping.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm3', 4, 'A gas accumulator on a feed line mainly helps pogo by…', '["Adding compliance, which lowers f_feed and absorbs pressure oscillations","Increasing tank pressure","Stiffening the structure","Shortening the burn"]', 0, 'Gas adds compliance (C = V/γp) and so moves the hydraulic frequency away from the structure and absorbs pulsations.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm3', 5, 'An oscillation in flight tracks the vehicle''s first axial mode as propellant depletes. Most likely…', '["Pogo","Chamber screech","ADC aliasing","Thermal drift"]', 0, 'A line that follows the structure indicates structural coupling, i.e. pogo.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('structures-vibration-dynamic-environments', 'm4', 'Dynamic environmental criteria', 'How launch environments are described, how test levels are chosen, and how to read a PSD or a shock spectrum.', 3);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 'm4', 'The dynamic environments and how they are tested', 25, 'Each environment, the test that represents it, and the margin philosophy behind test levels.', 0);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 0, 'IzlBgJ32dGA', 'Introduction to Vibration Control', 'Simcenter Physical Testing', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 0, 'p', '{"text":"A standard such as NASA-HDBK-7005 does not give you one number. It describes how to **define** each environment, derive **test criteria** from flight data or analysis and decide what to verify on the ground."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 1, 'table', '{"head":["Environment","Ground test","How the level is described"],"rows":[["Quasi-static acceleration","Centrifuge or static pull test","Load factors in g (axial and lateral)"],["Low-frequency sinusoidal / transient","Shaker sine sweep or burst","g (or displacement) versus frequency"],["Random vibration","Shaker random test","PSD (g²/Hz) and overall Grms"],["Acoustic","Reverberant chamber","Sound pressure level (dB) per ⅓-octave band"],["Shock","Shock rig, pyro firing, drop","Shock response spectrum (g vs Hz)"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 2, 'h', '{"text":"Levels and margin"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 3, 'p', '{"text":"Flight levels are uncertain, so test levels are set above the predicted maximum with a known margin. The vocabulary below is common across NASA and ESA practice. Always take the actual numbers from the document that governs *your* project."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 4, 'table', '{"head":["Test level","Meaning","Typical margin over flight prediction"],"rows":[["Acceptance","Screen each flight unit for workmanship defects","0 dB (flight level)"],["Protoflight","Qualify and accept a single flight unit","+3 dB"],["Qualification","Prove the design on a dedicated unit","+6 dB"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 5, 'callout', '{"kind":"tip","title":"dB for amplitude and for PSD","text":"A **+3 dB** margin on a PSD multiplies the PSD by ≈2 (and Grms by ≈1.41). **+6 dB** multiplies PSD by ≈4 (Grms by 2). Make sure you know whether a margin is quoted on PSD or on amplitude."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 6, 'callout', '{"kind":"warn","title":"Does this apply to a sounding rocket?","text":"Not directly. GEVS (GSFC-STD-7000), for example, excludes sounding rockets. Treat it as a source of **test philosophy and example levels**, and base your own criteria on measured flight data and the launcher''s user guide."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 0, 'Five environments, five tests: static, sine, random, acoustic and shock.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 1, 'Test levels = predicted maximum + margin (acceptance 0 dB, protoflight +3 dB, qualification +6 dB).');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 2, 'Standards give philosophy; project documents give the numbers. Check what a standard excludes.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 0, 'NASA-HDBK-7005 Dynamic Environmental Criteria', 'NASA', 'https://ntrs.nasa.gov/search?q=NASA-HDBK-7005', 'Team library #10');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'environments-overview', 1, 'GSFC-STD-7000 General Environmental Verification Standard (GEVS)', 'NASA GSFC', 'https://ntrs.nasa.gov/search?q=GSFC-STD-7000', 'Team library #38');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 'm4', 'Random vibration, PSD and Grms', 35, 'Reading a PSD, computing Grms, estimating a resonant response with Miles'' equation.', 1);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 0, '6apdZrgkElM', 'What is the PSD in Vibration', 'W5 Engineering', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 0, 'p', '{"text":"Random vibration is described statistically. The **power spectral density** (PSD) shows how the signal''s mean-square acceleration is distributed over frequency. Its unit is **g²/Hz**."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 1, 'eq', '{"text":"G_{\\mathrm{rms}} = \\sqrt{\\int \\mathrm{PSD}(f)\\,df}","name":"Grms from a PSD","caption":"The area under the PSD is the mean-square acceleration; its square root is the overall Grms"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 2, 'h', '{"text":"Reading a PSD specification"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 3, 'ul', '{"items":["Specs give **breakpoints** (f, g²/Hz) joined by straight lines on a log–log plot, and slopes in **dB/octave**.","A slope of +3 dB/oct means the PSD doubles each time frequency doubles (m = +1 on log–log).","A slope of −3 dB/oct means m = −1; the area of such a segment is W₁·f₁·ln(f₂/f₁)."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 4, 'lab', '{"id":"psd-grms"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 5, 'h', '{"text":"How big are the peaks?"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 6, 'p', '{"text":"For a Gaussian random signal, the instantaneous value exceeds 1σ (= Grms) about 32% of the time, 2σ about 4.6% and 3σ about 0.27%. Test engineers often quote **3σ peaks** as the practical maximum (3 × Grms) for design checks."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 7, 'h', '{"text":"Resonant response: Miles'' equation"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 8, 'eq', '{"text":"G_{\\mathrm{rms,resp}} \\approx \\sqrt{\\frac{\\pi}{2}\\, f_n\\, Q\\, \\mathrm{PSD}(f_n)}","name":"Miles'' equation","caption":"Valid for an SDOF system with a roughly flat input PSD near fn; fn in Hz, Q ≈ 1/2ζ"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 9, 'p', '{"text":"Example: fn = 200 Hz, Q = 10 and a PSD of 0.04 g²/Hz at 200 Hz: Grms_response = √(1.571 × 200 × 10 × 0.04) = √125.7 ≈ 11.2 Grms. The component sees about 11 Grms from a base input of only a few Grms."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 10, 'callout', '{"kind":"warn","title":"Limits","text":"A PSD assumes a stationary, Gaussian signal. Shock and transients are neither, so use an SRS (next lesson) for those. A PSD from a 2-second burn is also statistically weak: report the **resolution bandwidth** and number of averages."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 0, 'Grms = √(area under the PSD). dB/oct slopes are straight lines on a log-log plot.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 1, '3σ = 3 × Grms is the usual practical peak for Gaussian random vibration.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'random-vibration-psd', 2, 'Miles'' equation: Grms_resp ≈ √(π/2·fn·Q·PSD(fn)) estimates a resonant part''s response.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 'm4', 'Shock and the shock response spectrum', 30, 'Why a time history is not enough for a shock, and how an SRS turns it into a damage proxy.', 2);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 0, '5DI3xJ7KnYs', 'Shock and Drop Part 1: Generating a shock response spectrum (SRS)', 'Singularity Engineering LLC', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 0, 'p', '{"text":"Pyrotechnic stage separation, bolt cutters and valve slams produce brief, violent, non-stationary motion. Its **time history** is hard to compare between events, so we ask a more useful question: *how hard would a family of simple oscillators be shaken by this event?*"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 1, 'h', '{"text":"Building an SRS"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 2, 'ol', '{"items":["Choose a set of SDOF oscillators with natural frequencies spaced across the band of interest (for example ⅙-octave from 10 Hz to 10 kHz), all with the same Q (the convention is **Q = 10**, ζ = 5%).","Drive every oscillator''s base with the measured shock acceleration.","For each, record the **peak** absolute acceleration (usually the maximum of positive and negative peaks, the ''maximax'').","Plot peak acceleration versus oscillator frequency."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 3, 'lab', '{"id":"srs"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 4, 'h', '{"text":"Reading an SRS"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 5, 'ul', '{"items":["At **high** frequencies a stiff oscillator just follows the base, so the SRS approaches the **peak** acceleration of the pulse.","At **low** frequencies the oscillator barely responds to a short pulse; the SRS falls off steeply. On a log–log plot a typical slope is about +6 dB/oct (that is, proportional to frequency), set by the pulse''s velocity change.","A typical **pyroshock** SRS therefore rises at ≈ +6–12 dB/oct to a ''knee'' and then plateaus, anywhere from a few hundred g to many thousand g between 1 and 10 kHz."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 6, 'callout', '{"kind":"key","title":"What the SRS is not","text":"An SRS is **not** a spectrum of the shock and cannot be inverted back to a unique time history. Different pulses can share an SRS. It is a damage-potential comparison tool for small linear parts."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 7, 'callout', '{"kind":"warn","title":"Measurement implication","text":"Shock needs a **wide-band, high-range** sensor (often 10 kHz+ bandwidth and thousands of g), an anti-alias filter, and sample rates ≥ 10× the highest SRS frequency. A resonant sensor or an over-ranged amplifier can create a false low-frequency offset (''zero shift'') that wrecks the SRS. Lesson 5.1 returns to this."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 0, 'An SRS is the peak response of an array of SDOF oscillators (Q = 10 by convention) driven by the shock.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 1, 'It rises with frequency, then plateaus near the pulse peak. It is not a Fourier spectrum.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'shock-srs', 2, 'Shock measurement needs high range and bandwidth, and a sensor/amplifier that survive it.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 'm4', 'Margins, verification and what you can reuse', 25, 'Factors of safety, margin of safety, and how to adapt a CubeSat/GEVS test flow to a small rocket programme.', 3);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 0, '1O4PEqeXk5M', 'Vibration test of the CHEOPS satellite', 'ESA Space Science Hub', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 0, 'p', '{"text":"Verification means showing, by test, analysis, inspection or demonstration, that the design meets its requirements. For dynamics, a typical flow is:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 1, 'ol', '{"items":["**Modal survey / sine sweep** at low level to find fn and ζ.","**Sine burst or static test** to verify strength.","**Random vibration** at acceptance/protoflight/qualification level per axis, with low-level sweeps before and after to detect a shift in fn (a damage indicator).","**Shock test** if the unit sees pyro events.","**Functional test** after each step."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 2, 'callout', '{"kind":"tip","title":"The pre/post sweep","text":"A drop of more than a few percent in a first natural frequency after a test is a strong sign that something loosened or cracked. It is one of the cheapest and most useful measurements in the whole programme."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 3, 'h', '{"text":"Margin of safety"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 4, 'eq', '{"text":"\\mathrm{MS} = \\frac{\\text{Allowable load}}{\\mathrm{FoS}\\times\\text{Limit load}} - 1","name":"Margin of safety","caption":"MS ≥ 0 means the design passes. FoS is a factor of safety (commonly about 1.25 yield and 1.4 ultimate for unmanned metallic structures)"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 5, 'h', '{"text":"Reusing CubeSat and GEVS practice"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 6, 'ul', '{"items":["The **CubeSat Design Specification** (Rev 14.1) sets mechanical rules (envelope, mass, stiffness) and says tests follow the launch provider''s requirements.","GEVS gives example levels and a test flow, but excludes sounding rockets, so use it for structure, not for numbers.","For ASRI-type vehicles, the real flight levels should come from **instrumented test flights and static fires**, which is why this course ends with measurement."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 7, 'callout', '{"kind":"warn","title":"Safety","text":"Propellant handling, LOX operations and igniter work belong to the fluids and propulsion engineers. Your role in the test chain is data acquisition: hardware arm switches, fail-safe defaults and sensors that cannot create an ignition or leak path."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 0, 'Always bracket a vibration test with low-level sweeps; a frequency shift flags damage.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 1, 'MS = allowable / (FoS × limit) − 1. Zero or positive passes.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 2, 'Reuse test philosophy from CubeSat/GEVS; derive levels from your own flight and static-fire data.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'test-philosophy', 0, 'CubeSat Design Specification Rev. 14.1', 'Cal Poly CubeSat Program', 'https://www.cubesat.org/cubesatinfo', 'Team library #36');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm4', 0, 'A +3 dB margin applied to a PSD multiplies the PSD by about…', '["1.4","2","3","4"]', 1, '+3 dB in power is ×2 (Grms rises ×1.41).');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm4', 1, 'Which gives the overall Grms of a random vibration spec?', '["Peak of the PSD","√(area under the PSD)","Average of the breakpoints","PSD at the first resonance"]', 1, 'The area under the PSD is mean-square; its square root is Grms.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm4', 2, 'For a Gaussian signal, 3σ peaks are about…', '["Equal to Grms","1.5 × Grms","3 × Grms","10 × Grms"]', 2, 'σ = Grms for a zero-mean signal, so 3σ = 3 × Grms.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm4', 3, 'Miles'' equation with fn = 100 Hz, Q = 10 and PSD = 0.04 g²/Hz gives about…', '["4.0 Grms","7.9 Grms","62 Grms","630 Grms"]', 1, '√(1.571 × 100 × 10 × 0.04) = √62.8 = 7.9 Grms.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm4', 4, 'The standard Q used when computing an SRS is…', '["1","5","10","100"]', 2, 'The conventional SRS uses Q = 10 (ζ = 5%).');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm4', 5, 'A pre/post-test sweep shows fn dropped from 210 Hz to 188 Hz. What does this most likely indicate?', '["Better damping","Sensor drift only","Possible loosening or damage","A calibration success"]', 2, 'A drop of >5% in fn after a test usually means stiffness loss, e.g. loose fasteners or cracks.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('structures-vibration-dynamic-environments', 'm5', 'Measuring vibration', 'Choose the sensor, mount it, sample it, wire it and analyse it so the numbers can be trusted.', 4);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'sensors', 'm5', 'Choosing an accelerometer', 30, 'Piezoelectric, piezoresistive and MEMS capacitive sensors: what each is good (and bad) at.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sensors', 0, 'p', '{"text":"Every accelerometer is an SDOF system: a seismic mass on a spring, with some transduction. The transduction method determines almost everything about how you can use it."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sensors', 1, 'table', '{"head":["Type","Strengths","Limits","Typical use"],"rows":[["Piezoelectric, IEPE/ICP (voltage mode)","Wide band (to 10 kHz+), low noise, simple cable, rugged","AC-coupled: no response to steady acceleration (typically < ~0.5 Hz rolled off)","Engine and structure vibration, modal tests"],["Piezoelectric, charge mode","High temperature, very wide dynamic range","Needs a charge amplifier and low-noise cable","Hot-section and shock work"],["Piezoresistive (strain-gauge)","True DC response, very high-g, shock-hardened versions","Higher noise, needs bridge excitation, temperature drift","Pyroshock, ballistic, quasi-static + vibration"],["MEMS capacitive","DC response, small and cheap, digital output common","Higher noise, limited bandwidth (typically ≲ 5 kHz), limited over-range","IMU, quasi-static and low-frequency flight data"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sensors', 2, 'h', '{"text":"The specification sheet in five numbers"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sensors', 3, 'ul', '{"items":["**Range** (±g): must cover the real peak with margin. Clipping destroys the data.","**Sensitivity** (mV/g or mV/V/g): sets how much signal you get into the DAQ.","**Frequency response** (±5% or ±1 dB band): where the sensor is accurate.","**Mounted resonance:** sets the usable band and shock survivability; see the next lesson.","**Noise floor** (µg/√Hz) and **shock limit** (g)."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sensors', 4, 'callout', '{"kind":"key","title":"An IMU is not a vibration sensor","text":"A flight IMU is built for attitude and trajectory: ±g range, gyro rate range and a ~1 kHz sample rate, usually with built-in low-pass filtering. It will alias or filter vibration above a few hundred Hz. Use a dedicated accelerometer channel with its own anti-alias filter for vibration and shock."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sensors', 5, 'callout', '{"kind":"tip","title":"Matching the sensor to the job","text":"Starting envelope used in this programme''s planning: ±200 g boost-phase accelerometer, a 10 kHz vibration bandwidth sampled at about 25 kHz, and an IMU at 1 kHz. Replace these with ASRI''s real numbers when available."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sensors', 0, 'Piezoelectric: best for AC vibration; piezoresistive: DC and shock; MEMS: cheap DC but noisy and band-limited.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sensors', 1, 'Check range, sensitivity, band, mounted resonance, noise floor and shock limit.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sensors', 2, 'An IMU does not replace a vibration accelerometer; give vibration its own filtered channel.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'sensors', 0, 'PCB Piezotronics: Vibration Fundamentals quick reference', 'PCB Piezotronics', NULL, 'Team library #22');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'installation', 'm5', 'Accelerometer installation and mounting', 30, 'How the way you attach the sensor limits the frequency band you can trust.', 1);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'installation', 0, '8yYyYMFnub8', 'How Accelerometer Mounting Changes Your Vibration Data | Stud vs Adhesive vs Magnet', 'BCNT TECHNOLOGIES', NULL);
INSERT INTO lesson_videos (course_slug, lesson_id, position, youtube_id, title, channel, start) VALUES ('structures-vibration-dynamic-environments', 'installation', 1, '_2114sRSZ5k', 'Want To Get Your Accelerometer Installations Perfect?', 'Alstom MSc', NULL);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'installation', 0, 'p', '{"text":"A sensor''s quoted frequency response applies when it is **stud-mounted to a flat, clean, rigid surface**. Every other mounting adds compliance and mass, **lowers the mounted resonance**, and shrinks the usable band."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'installation', 1, 'eq', '{"text":"\\text{Error} \\approx \\frac{1}{1-r^2} - 1, \\qquad r = \\frac{f}{f_{\\text{mounted}}}","name":"Mounting error","caption":"Amplitude error of a lightly damped sensor below its mounted resonance. At r = 1/5 the error is ≈ +4%, at r = 1/3 about +12.5%"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'installation', 2, 'lab', '{"id":"mounting"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'installation', 3, 'table', '{"head":["Mounting","Relative stiffness","Notes"],"rows":[["Threaded stud (steel, torqued)","Best","Reference condition. Spot-face, thin film of couplant, stud must not bottom out"],["Adhesive (cyanoacrylate / epoxy)","Good if thin","Thin bond line, clean surface; use a mounting pad to protect the structure"],["Adhesive wax","Fair, low temperature only","Quick and cheap; creeps with temperature and large g"],["Magnet","Moderate","Ferrous surface only; limited band and g-level"],["Hand-held probe","Poor","Diagnostics only, not data you will quote"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'installation', 4, 'h', '{"text":"Installation checklist (after Endevco TP319)"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'installation', 5, 'ul', '{"items":["Prepare the surface: flat, clean and degreased; no paint or burrs under the base.","Choose the orientation so the sensor''s sensitive axis lines up with the axis you want. Use a **tri-axial** block at the engine mount and at payload interface.","Place it near the load path or hardware of interest, not on a thin panel that has its own modes.","**Mass loading:** the sensor and its pad should be ≲ 10% of the local dynamic mass, otherwise it changes the thing it measures.","Strain-relieve the cable close to the sensor (tape/clamp, with a small loop) so cable whip cannot drive the sensor.","Use an electrically isolated mounting base where the structure is a ground path, to avoid ground loops.","Record the position, axis, serial number and calibration date in the test log. Photograph each install."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'installation', 6, 'callout', '{"kind":"warn","title":"Check the mounting by tapping","text":"A fast field check: tap near the sensor and watch the spectrum. A mounted resonance far below the datasheet value means a loose or bottomed-out stud, or too thick an adhesive layer. It is much cheaper to find that before the test."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'installation', 0, 'Stud mounting reproduces the datasheet; every other mount lowers the resonance and band.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'installation', 1, 'Trust data up to about ⅕ of the mounted resonance (≈4%) or ⅓ (≈12%).');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'installation', 2, 'Surface prep, orientation, mass loading, cable strain relief and isolation are all part of the install.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'installation', 0, 'Guidelines for Mounting Test Accelerometers', 'PCB Piezotronics', 'https://www.pcb.com/Resources/TechnicalInformation/Mounting', NULL);
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'installation', 1, 'Endevco TP319 Guide to Accelerometer Installation', 'Endevco', NULL, 'Team library #23');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 'm5', 'Sampling, aliasing and anti-alias filtering', 30, 'Why the data acquisition front end matters more than the sample rate on the box.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 0, 'p', '{"text":"Sampling a signal at **fs** can only represent frequencies below **fs/2** (Nyquist). Anything above folds back into that band at the **alias frequency**:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 1, 'eq', '{"text":"f_{\\text{alias}} = \\left| f - k f_s \\right|, \\qquad k = \\operatorname{round}(f/f_s)","name":"Alias frequency","caption":"A 9 kHz tone sampled at 10 kHz shows up at 1 kHz, and it is indistinguishable from a real 1 kHz tone"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 2, 'lab', '{"id":"aliasing"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 3, 'callout', '{"kind":"key","title":"You cannot remove aliasing after sampling","text":"Once folded, the alias is part of your data. The only cure is an **analogue anti-alias filter** before the ADC (or an oversampling converter that filters digitally) set to remove energy above the band you care about."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 4, 'h', '{"text":"Practical rules"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 5, 'ul', '{"items":["Pick the bandwidth **BW** you need (e.g. 10 kHz for engine vibration).","Use **fs ≥ 2.56 × BW** (the classic analyser factor) so a real filter''s roll-off has room: 10 kHz → ≥ 25.6 kS/s.","Choose the anti-alias filter corner at or just above BW with enough attenuation at fs/2 (a steep 4th–8th order, or a sigma-delta ADC).","For shock and time-history work, sample **≥ 10×** the highest frequency of interest to keep the peak.","Storage is rarely the limit on a test stand: 4 channels × 25 kS/s × 2 bytes ≈ 200 KB/s."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 6, 'callout', '{"kind":"tip","title":"Connection to your DSP background","text":"This is the same Nyquist/anti-alias design you know from the DSP guide and TI application notes SBAA282 and SBAA655 (library #19, #20). The vibration-specific parts are the **bandwidth you choose** and the fact that an accelerometer''s own resonance, at 20–50 kHz, can sit above your filter and still excite it if the ADC has no analogue filter."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 0, 'Frequencies above fs/2 fold to f_alias = |f − k·fs| and cannot be undone.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 1, 'Use fs ≥ 2.56 × BW with an analogue (or oversampling) anti-alias filter.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 2, 'For shock, sample ≥ 10× the highest frequency of interest.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 0, 'TI SBAA282: Antialiasing Filter Circuit Design', 'Texas Instruments', NULL, 'Team library #19');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 1, 'TI SBAA655: Anti-Aliasing Filter Design for a 100 kHz DAQ', 'Texas Instruments', NULL, 'Team library #20');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 'sampling-aliasing', 2, 'The Scientist and Engineer''s Guide to DSP (S.W. Smith)', 'dspguide.com', 'https://www.dspguide.com/', 'Team library: dspguide_smith');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 'm5', 'The signal chain: conditioning, cables and noise', 25, 'IEPE excitation, grounding, cable noise and the dynamic range budget from sensor to file.', 3);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 0, 'p', '{"text":"From sensor to stored file the signal passes through: **sensor → cable → conditioner/excitation → anti-alias filter → ADC → storage**. Each step can add error."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 1, 'h', '{"text":"IEPE/ICP conditioning"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 2, 'ul', '{"items":["The DAQ provides a **constant current** (commonly 2–20 mA) over the same coax cable that carries the signal, at a compliance voltage of about 18–30 V.","The signal rides on a DC bias (≈ 8–12 V) that is AC-coupled away. A bias reading outside its normal window reveals an open or short circuit cable: use it as a free health check.","Cable length is rarely limiting with low-impedance IEPE sensors, but long runs lose high-frequency headroom at high g and large signal swings."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 3, 'h', '{"text":"Grounding and noise"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 4, 'ul', '{"items":["Ground the shield at **one end** (usually the DAQ) to avoid ground loops.","Keep signal cables away from ignition leads, valve drivers and power cables; cross at right angles.","In charge-mode systems, use low-noise cable: ordinary coax produces ''triboelectric'' charge when flexed.","Let each channel carry **TEDS** (sensor identity and calibration) if supported, to avoid sensitivity transcription errors."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 5, 'h', '{"text":"Dynamic range budget"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 6, 'p', '{"text":"A 16-bit ADC with a ±5 V range has a step of ≈ 0.15 mV. A 10 mV/g accelerometer on ±5 V uses ±500 g of range, but the 0.15 mV step is just 0.015 g. Pick the sensitivity and gain so the **expected peak uses at least about half the ADC range**, leaving headroom for surprises but not wasting resolution."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 7, 'lab', '{"id":"sensor-chain"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 8, 'callout', '{"kind":"warn","title":"Never trust the first record","text":"Before every test: tap-test each channel, confirm the bias voltage, check the polarity of the axis against the test coordinate frame and record a short quiet baseline. The baseline is the noise floor against which you judge every later spectrum."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 0, 'IEPE: constant-current excitation over the signal cable; the bias voltage doubles as a health check.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 1, 'One-ended shield grounding, cable separation and strain relief avoid most noise problems.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'signal-chain', 2, 'Size gain so the expected peak uses about half the ADC range; always record a quiet baseline.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 'm5', 'Analysing vibration data', 35, 'Time history, PSD and Grms from your own data: use the built-in analyser on a CSV of acceleration.', 4);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 0, 'p', '{"text":"Real data needs the same three views you have seen in this course: the **time history** (does it look sane? is it clipped?), the **PSD** (where is the energy?) and the **summary numbers** (Grms, peak)."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 1, 'ol', '{"items":["**Inspect the time history.** Flat tops mean clipping; a step or drift suggests zero shift or a bias fault; periodic spikes can be interference.","**Compute the PSD** with Welch averaging (windowed, overlapping segments). More averages mean a smoother estimate but lower frequency resolution (Δf = fs/N).","**Compare** against the specification PSD, and look for narrow lines (tonal sources such as pump speed, or pogo) versus broad humps (resonances).","**Report** Grms over a stated band, the resolution bandwidth and number of averages."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 2, 'callout', '{"kind":"tip","title":"Use your own data","text":"Load a CSV of acceleration (one column, or time + acceleration columns) from a bench test, phone app or logger. Pick the sample rate, and the analyser runs entirely in your browser. Nothing is uploaded. No data? Press ''Demo signal'' for a synthetic record with two tones and noise."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 3, 'lab', '{"id":"psd-analyzer"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 4, 'h', '{"text":"Common pitfalls"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 5, 'ul', '{"items":["Wrong sample rate entered, so every frequency is scaled incorrectly.","DC offset in the record (the analyser removes the mean, but real systems should be AC-coupled).","Too short a record: fewer than ~10 averages gives noisy PSD estimates.","Mixing units (m/s² versus g): 1 g = 9.80665 m/s²."]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 0, 'Always look at the time history first: clipping, offsets and spikes show up there.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 1, 'Welch PSD: more averages, lower resolution. Report Δf and averages.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'analysing-data', 2, 'State units, band and sample rate with every Grms you quote.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm5', 0, 'Which sensor type gives a true DC (steady acceleration) response and survives very high-g shock?', '["IEPE piezoelectric","Piezoresistive","Microphone","Charge-mode piezoelectric"]', 1, 'Piezoresistive sensors respond to DC and come in shock-hardened versions.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm5', 1, 'At what fraction of the mounted resonance is the amplitude error of a lightly damped accelerometer about +4%?', '["1/2","1/3","1/5","1/10"]', 2, '1/(1−0.2²) − 1 = 0.0417, so about +4%.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm5', 2, 'A 7 kHz tone is sampled at 10 kHz. It appears at…', '["7 kHz","3 kHz","5 kHz","17 kHz"]', 1, 'f_alias = |7 − 1×10| = 3 kHz.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm5', 3, 'You need a 10 kHz vibration bandwidth with a practical anti-alias filter. A sensible sample rate is…', '["20 kS/s","≥ 25.6 kS/s","10 kS/s","5 kS/s"]', 1, 'The classic factor is 2.56 × bandwidth.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm5', 4, 'In an IEPE system, an unusually high or low DC bias on a channel most likely means…', '["Better data","An open or shorted cable/sensor","The wrong sample rate","A calibration pass"]', 1, 'Bias outside the normal window is a built-in health check for cable and sensor faults.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm5', 5, 'Why should an IMU not be the only vibration sensor on a rocket?', '["IMUs are too accurate","It lacks a gyroscope","Built-in filtering and ~1 kHz sampling alias or remove higher-frequency vibration","It cannot measure acceleration"]', 2, 'IMUs are designed for attitude and trajectory; vibration needs its own wide-band, anti-aliased channel.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('structures-vibration-dynamic-environments', 'm6', 'Capstone: a measurement plan', 'Pull the course together into a defensible vibration and dynamics measurement plan for an engine test stand and flight.', 5);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 'm6', 'Capstone: write your measurement plan', 60, 'Choose channels, ranges, bandwidth and mounting, then document it in the notes tab and attach supporting files.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 0, 'p', '{"text":"Your capstone is a **one-to-two page measurement plan** for vibration and dynamic environments on a liquid-engine test stand or a sounding-rocket flight. Write it in the **Notes** tab of this lesson (it is saved on this device), and attach any supporting files (datasheets, sketches, spreadsheets) in the **Files** tab."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 1, 'h', '{"text":"Required sections"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 2, 'ol', '{"items":["**Objective and unknowns:** what decision will this data support (design margin, pogo check, qualification levels)? What is unknown today (peak g, roll rate, burn time)?","**Environment forecast:** which of the five environments apply and the expected frequency range of each.","**Channel list:** for each channel give location, axis, sensor type, range, sensitivity, mounting method, and why that location.","**Signal chain:** conditioning type, cable plan, grounding, anti-alias filter corner, sample rate, resolution and storage, using the sizing lab below.","**Pogo / instability instrumentation:** dynamic pressure and axial acceleration, time-aligned.","**Pre/post checks:** tap tests, bias check, baseline record and low-level sweeps.","**Safety and fail-safes:** hardware arm switches, default states and a statement of what the DAQ is allowed to touch (data only).","**Analysis plan:** time history review, PSD parameters, SRS if shock, acceptance criteria."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 3, 'lab', '{"id":"sensor-chain"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 4, 'h', '{"text":"Self-check"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 5, 'ul', '{"items":["Can you justify every channel''s **range** with a number and a margin?","If a stud mount is not possible, have you shown the usable bandwidth for your actual mount?","Is there an anti-alias filter before every ADC channel?","Does your plan say what you will do when the first record looks wrong?"]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 6, 'callout', '{"kind":"tip","title":"Complete the course","text":"Mark this lesson complete when your plan is written. Pass all module quizzes (≥ 70%) and complete every lesson to unlock your certificate."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 0, 'A good plan states the decision the data supports before choosing any hardware.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 1, 'Every channel needs a location, range, sensitivity, mounting, bandwidth and justification.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('structures-vibration-dynamic-environments', 'measurement-plan', 2, 'Safety, health checks and baselines belong in the plan, not as afterthoughts.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm6', 0, 'What should a measurement plan establish FIRST?', '["The most expensive sensor","The decision the data will support","The file format","The sample rate"]', 1, 'Requirements drive every other choice: ranges, bandwidth and sensors.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm6', 1, 'Which pair of channels best supports a pogo investigation?', '["Temperature and humidity","Axial acceleration and dynamic chamber/inlet pressure, time-aligned","GPS position and battery voltage","Strain gauge only"]', 1, 'Pogo is an acceleration–pressure coupling; both must share a clock.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm6', 2, 'A channel''s expected peak is 40 g and you must choose between ±50 g and ±500 g sensors with similar noise. A good approach is…', '["Always pick the largest range","Pick the range that comfortably covers the peak with margin, without wasting resolution","Pick the smallest range regardless of clipping","Pick the cheapest"]', 1, 'Cover the peak with margin but keep resolution; clipping destroys data and excess range buries it in noise.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('structures-vibration-dynamic-environments', 'm6', 3, 'Where does the DAQ sit in the safety design?', '["It controls the valves","It records data only, with hardware arm switches and fail-safe defaults for anything it can affect","It arms the igniter","It is exempt from review"]', 1, 'Keep acquisition separate from propulsion actuation; fail-safe and hardware-armed.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 0, 'Natural frequency (fn)', 'm1', 'The frequency at which a system oscillates freely after a disturbance. For an SDOF oscillator fn = √(k/m)/2π.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 1, 'Damping ratio (ζ)', 'm1', 'Damping as a fraction of critical damping. ζ = c / (2√(km)). Metal structures are typically 0.5–5%.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 2, 'Q factor', 'm1', 'Quality factor, roughly 1/(2ζ). The approximate amplification at resonance.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 3, 'Logarithmic decrement', 'm1', 'δ = ln(x₁/x₂) between successive peaks of a free decay; δ ≈ 2πζ for light damping.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 4, 'Transmissibility', 'm1', 'Ratio of response to input amplitude for a base-excited system, as a function of frequency ratio.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 5, 'Mode shape', 'm2', 'The relative pattern of displacement of a structure when it vibrates at one natural frequency.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 6, 'Modal mass', 'm2', 'The mass associated with a mode for a chosen normalisation; the effective modal mass is the part that participates for a given excitation.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 7, 'Effective modal mass', 'm2', 'The share of total mass that moves in a given mode for a given excitation direction. Effective masses sum to total mass.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 8, 'Coupled loads analysis (CLA)', 'm2', 'Analysis that combines launch-vehicle and payload dynamic models to predict loads at the interface and in the payload.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 9, 'Free–free', 'm2', 'Boundary condition with no supports. A launch vehicle in flight is approximately free–free.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 10, 'Pogo', 'm3', 'Self-excited instability coupling a vehicle''s axial structural mode with propulsion feed-system pressure and thrust oscillations.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 11, 'Accumulator', 'm3', 'A gas-filled volume on a propellant line that adds compliance and absorbs pressure pulsations; used to suppress pogo.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 12, 'Inertance', 'm3', 'Hydraulic ''mass'' of a fluid in a line: I = ρL/A.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 13, 'Compliance (hydraulic)', 'm3', 'Hydraulic ''spring'': volume change per unit pressure. For a gas volume C = V/(γp).');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 14, 'Chugging', 'm3', 'Low-frequency combustion instability coupled with the feed system, not the structure.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 15, 'Quasi-static load', 'm3', 'Load that varies slowly enough for the structure to respond as if the load were static.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 16, 'Dynamic load factor', 'm3', 'Ratio of peak dynamic response to static response. Up to 2 for an undamped SDOF system under a step force.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 17, 'PSD (power spectral density)', 'm4', 'Distribution of mean-square signal over frequency, in g²/Hz for acceleration.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 18, 'Grms', 'm4', 'Root-mean-square acceleration; the square root of the area under the PSD.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 19, 'Octave', 'm4', 'A doubling of frequency. PSD slopes are often given in dB per octave.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 20, 'Miles'' equation', 'm4', 'Grms_response ≈ √((π/2)·fn·Q·PSD(fn)): response of an SDOF system to a flat random base input.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 21, 'Shock response spectrum (SRS)', 'm4', 'Peak response of a family of SDOF oscillators (usually Q = 10) to a transient, plotted against their natural frequency.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 22, 'Maximax', 'm4', 'The largest absolute response, positive or negative, across the whole record; the usual SRS definition.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 23, 'Pyroshock', 'm4', 'Shock from pyrotechnic devices such as separation bolts and cutters, with high-frequency content to 10 kHz and beyond.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 24, 'Qualification test', 'm4', 'Test of a dedicated unit at levels above flight (typically flight prediction +6 dB) to prove the design.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 25, 'Protoflight test', 'm4', 'Test of a single flight unit at qualification-like levels but shorter duration (typically +3 dB).');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 26, 'Acceptance test', 'm4', 'Test of each flight unit at flight level to screen for workmanship defects.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 27, 'Margin of safety (MS)', 'm4', 'MS = allowable / (FoS × limit load) − 1. Non-negative means the design passes.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 28, 'Accelerometer', 'm5', 'Sensor that outputs a signal proportional to acceleration; internally an SDOF seismic-mass system.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 29, 'IEPE / ICP', 'm5', 'Integrated Electronics Piezo-Electric: a piezoelectric sensor with built-in amplifier powered by a constant-current line.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 30, 'Piezoresistive sensor', 'm5', 'Accelerometer using strain-sensitive resistors; has DC response and can survive high-g shock.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 31, 'MEMS accelerometer', 'm5', 'Micro-machined silicon accelerometer, usually capacitive, with DC response, small size and higher noise.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 32, 'Mounted resonance', 'm5', 'The sensor''s resonance as installed; it is lower than the free value and sets the usable bandwidth.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 33, 'Mass loading', 'm5', 'Change in the structure''s dynamics caused by the added mass of a sensor.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 34, 'Nyquist frequency', 'm5', 'Half the sampling rate. Higher frequencies fold into the sampled band.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 35, 'Aliasing', 'm5', 'Folding of out-of-band frequency content into the sampled band: f_alias = |f − k·fs|.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 36, 'Anti-alias filter', 'm5', 'Analogue low-pass filter before the ADC that removes content above the band of interest.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 37, 'Welch method', 'm5', 'PSD estimate by averaging windowed, overlapping segments'' periodograms.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 38, 'Resolution bandwidth', 'm5', 'Frequency spacing Δf = fs/N of a PSD; must be stated with any PSD.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 39, 'Ground loop', 'm5', 'Unintended current path via multiple ground connections that injects noise into a measurement.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 40, 'Triboelectric noise', 'm5', 'Charge generated by flexing coax cable; a problem in charge-mode accelerometer systems.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 41, 'TEDS', 'm5', 'Transducer Electronic Data Sheet: sensor identity and calibration stored on the sensor itself.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('structures-vibration-dynamic-environments', 42, 'Dynamic environment', 'm1', 'The mechanical loading arising from motion: vibration, shock, acoustics and transients.');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 0, 'NASA-HDBK-7005 Dynamic Environmental Criteria', 'NASA', 'https://ntrs.nasa.gov/search?q=NASA-HDBK-7005', 'Core reference for modules 3–4 (library #10)');
