INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 2, 'NASA SP-8113 Liquid Rocket Engine Combustion Stabilization Devices', 'NASA', 'https://ntrs.nasa.gov/search?q=Liquid%20Rocket%20Engine%20Combustion%20Stabilization%20Devices', 'Library #07');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 3, 'Transient Loads from Thrust Excitation (NASA Space Vehicle Design Criteria)', 'NASA', 'https://ntrs.nasa.gov/search?q=Transient%20Loads%20from%20Thrust%20Excitation', 'Library #09');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 4, 'GSFC-STD-7000 GEVS', 'NASA GSFC', 'https://ntrs.nasa.gov/search?q=GSFC-STD-7000', 'Library #38. Excludes sounding rockets');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 5, 'CubeSat Design Specification Rev. 14.1', 'Cal Poly', 'https://www.cubesat.org/cubesatinfo', 'Library #36');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 6, 'PCB Piezotronics: Vibration Fundamentals quick reference', 'PCB Piezotronics', NULL, 'Library #22');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 7, 'Endevco TP319: Guide to Accelerometer Installation', 'Endevco', NULL, 'Library #23');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 8, 'Guidelines for Mounting Test Accelerometers', 'PCB Piezotronics', 'https://www.pcb.com/Resources/TechnicalInformation/Mounting', NULL);
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 9, 'MIT 2.003SC Engineering Dynamics (full course)', 'MIT OpenCourseWare', 'https://ocw.mit.edu/courses/2-003sc-engineering-dynamics-fall-2011/', 'Lectures 19–27 are used in modules 1–2');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 10, 'The Scientist and Engineer''s Guide to Digital Signal Processing', 'S. W. Smith', 'https://www.dspguide.com/', 'Library: dspguide_smith');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 11, 'TI SBAA282 / SBAA655: anti-aliasing filter design', 'Texas Instruments', NULL, 'Library #19, #20');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('structures-vibration-dynamic-environments', 12, 'Chowdhury 2012: sounding rocket flight dynamics; Williams 2020: composite tanks', 'UKZN ASRI theses', NULL, 'Library: ukzn_asri_theses');
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'q-zeta', 'm1', 'Q and damping', '$Q \approx 1/(2\zeta)$. Metal structures have $\zeta \approx 0.5\text{–}5\%$ so $Q \approx 10\text{–}100$. Use **Q = 10** when damping is unknown.', 0);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'decay-cycles', 'm1', 'Free decay rule', 'Amplitude halves in about $0.11/\zeta$ cycles. $\zeta = 1\%$ halves in roughly 11 cycles.', 1);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'isolation-onset', 'm1', 'When isolation starts', 'Transmissibility is below 1 only for $r = f/f_n > \sqrt{2}$. More damping lowers the peak but **raises** transmissibility above $\sqrt{2}f_n$.', 2);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'fn-quick', 'm1', 'Quick frequency check', '1 kg on 1 kN/m gives $f_n \approx 5.03$ Hz. Quadrupling the mass halves the frequency.', 3);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'beam-constants', 'm2', 'Beam constants $\beta_n L$', 'Cantilever **1.875, 4.694, 7.855**. Free–free (vehicle in flight) **4.730, 7.853, 10.996**. Pinned–pinned $n\pi$.', 4);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'axial-rod', 'm2', 'Axial modes of a rod', 'Fixed–free: $f_n = \dfrac{2n-1}{4L}\sqrt{E/\rho}$. Speed of sound: aluminium ≈ 5 090 m/s, steel ≈ 5 050 m/s.', 5);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'modal-mass', 'm2', 'How many modes to keep', 'Keep enough modes that their effective masses add to **≥ 90%** of total mass in each excitation direction.', 6);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'freq-scaling', 'm2', 'Scaling', 'Bending $f \propto 1/L^2$, axial $f \propto 1/L$. In flight, mode frequencies **rise** as propellant burns off.', 7);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'dlf', 'm3', 'Dynamic load factor', 'A step force on an undamped SDOF gives a peak of $2F/k$. A ramp longer than about 2–3 structural periods removes most overshoot.', 8);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'freq-bands', 'm3', 'Oscillation bands (rough)', 'Pogo ≈ 5–60 Hz (tracks the structure). Chugging ≈ 10–400 Hz (feed system and chamber). Screech ≳ 1 kHz (chamber acoustics).', 9);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'pogo-check', 'm3', 'Pogo first check', 'Compute $f_{feed} = 1/(2\pi\sqrt{IC})$ and compare with the first axial mode. Avoid coincidence; add compliance (accumulator) or damping.', 10);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'db-rules', 'm4', 'dB rules for PSD', '+3 dB = PSD ×2 (Grms ×1.41). +6 dB = PSD ×4 (Grms ×2). A slope of +3 dB/oct is $m = +1$ on log–log.', 11);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'sigma', 'm4', 'Peaks', 'Gaussian random: 3σ peak = **3 × Grms**, exceeded about 0.27% of the time.', 12);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'test-levels', 'm4', 'Test levels', 'Acceptance 0 dB, protoflight **+3 dB**, qualification **+6 dB** over the predicted flight maximum. Take actual numbers from the governing document.', 13);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'srs-q', 'm4', 'SRS conventions', 'Q = 10 (ζ = 5%), maximax absolute acceleration. High-frequency plateau ≈ pulse peak; low-frequency side rises ≈ +6 dB/oct.', 14);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'ms', 'm4', 'Factors of safety', 'Common unmanned metallic values: **1.25** yield, **1.4** ultimate. $MS \ge 0$ passes.', 15);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'pre-post', 'm4', 'Pre/post sweep', 'A drop of more than about 5% in the first natural frequency after a test suggests loosening or damage.', 16);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'mount-band', 'm5', 'Usable accelerometer band', 'Trust data to about $f_{mounted}/5$ (≈ +4%) or $f_{mounted}/3$ (≈ +12.5%). Stud mounting reproduces the datasheet; every other mount lowers it.', 17);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'sampling', 'm5', 'Sampling', '$f_s \ge 2.56 \times$ bandwidth behind an analogue anti-alias filter (10 kHz → ≥ 25.6 kS/s). For shock use ≥ **10×** the highest frequency of interest.', 18);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'iepe', 'm5', 'IEPE / ICP', 'Constant current 2–20 mA, compliance 18–30 V, bias about 8–12 V. A bias outside its normal window flags an open or shorted cable.', 19);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'adc-range', 'm5', 'ADC range', '$LSB = 2V_{fs}/2^N$. Size gain so the expected peak uses about **half** the ADC range. 16 bit on ±5 V is 0.153 mV per step.', 20);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'wiring', 'm5', 'Wiring', 'Ground the shield at **one end**. Keep signal cables away from ignition and valve drivers. Strain-relieve the cable near the sensor. Sensor mass ≲ 10% of local dynamic mass.', 21);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('structures-vibration-dynamic-environments', 'plan-checklist', 'm6', 'Plan checklist', 'Decision the data supports; environments and bands; per-channel range, sensitivity, mount, bandwidth; anti-alias and sample rate; pogo pair (axial acceleration + dynamic pressure); pre/post checks; fail-safes; analysis plan.', 22);
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-zeta', 'm1', 'Damping ratio from two decay peaks', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-transmissibility', 'm1', 'Base-excitation transmissibility', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-tube', 'm2', 'Bending modes of a uniform tube', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-feed', 'm3', 'Feed-line hydraulic frequency', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-grms', 'm4', 'Grms from PSD breakpoints', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-srs', 'm4', 'Shock response spectrum (maximax)', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-welch', 'm5', 'PSD and Grms from measured data', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-alias', 'm5', 'Alias frequency and anti-alias filter', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('structures-vibration-dynamic-environments', 'py-chain', 'm5', 'Sensor-chain sizing', 'python', 'import numpy as np
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('structures-vibration-dynamic-environments', 'm1-problems', 'm1', 'SDOF oscillator problems', 'Natural frequency, damping from decay, resonance and isolation.', 'problems', 0);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm1-problems', 'm1-p1', 0, 'numeric', 1, 'A 2.5 kg mass sits on a spring of stiffness 10 kN/m. What is its natural frequency?', '$f_n = \frac{1}{2\pi}\sqrt{k/m}$. Convert kN/m to N/m first.', '$\omega_n = \sqrt{k/m} = \sqrt{10000/2.5} = \sqrt{4000} = 63.25$ rad/s.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm1-problems', 'm1-p2', 1, 'numeric', 2, 'Two successive peaks of a free decay, one period apart, are 12.0 mm and 9.6 mm. Find the damping ratio $\zeta$.', 'First the log decrement $\delta = \ln(x_1/x_2)$. Then $\zeta = \delta / \sqrt{4\pi^2 + \delta^2}$.', '$\delta = \ln(12.0/9.6) = \ln 1.25 = 0.2231$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm1-problems', 'm1-p3', 2, 'numeric', 2, 'A bracket has $\zeta = 0.02$. A 0.5 g sine base input is applied exactly at its natural frequency. About what peak acceleration (in g) does the mounted component see?', 'At resonance the amplification is about $Q \approx 1/(2\zeta)$.', '$Q \approx 1/(2 \times 0.02) = 25$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm1-problems', 'm1-p4', 3, 'numeric', 2, 'An isolator has $\zeta = 0.1$. Find the transmissibility $T$ at a frequency ratio $r = 2$.', '$T = \sqrt{\dfrac{1 + (2\zeta r)^2}{(1 - r^2)^2 + (2\zeta r)^2}}$', '$2\zeta r = 0.4$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm1-problems', 'm1-p5', 4, 'numeric', 1, 'An avionics tray is mounted on isolators with a natural frequency of 8 Hz. Above what frequency does it begin to attenuate vibration?', 'Attenuation starts where $T < 1$, which is for $r > \sqrt{2}$.', '$T < 1$ once $r > \sqrt{2}$, regardless of damping.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm1-problems', 'm1-p6', 5, 'written', 3, 'Explain why adding damping to an isolator lowers the resonant peak but can make high-frequency isolation worse. When would you accept that trade?', NULL, 'Damping removes energy near resonance, so the peak falls from about $Q$ to something smaller.
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('structures-vibration-dynamic-environments', 'm2-problems', 'm2', 'Modes, beams and rods', 'Hand checks for tube frequencies, axial modes and modal participation.', 'problems', 1);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm2-problems', 'm2-p1', 0, 'numeric', 3, 'An aluminium tube ($E = 70$ GPa, $\rho = 2700$ kg/m³) is 3.0 m long, 150 mm outer diameter with a 2 mm wall. Treat it as free-free. Find the first bending frequency.', 'Use $f_1 = \dfrac{(\beta_1 L)^2}{2\pi L^2}\sqrt{EI/\rho A}$ with $\beta_1 L = 4.730$. Get $A$ and $I$ from the outer and inner radii.', '$r_o = 0.075$ m, $r_i = 0.073$ m.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm2-problems', 'm2-p2', 1, 'numeric', 3, 'The same tube is now clamped at one end (cantilever) for a shaker test. What is its first bending frequency?', 'Same $\sqrt{EI/\rho A}$, but $\beta_1 L = 1.875$.', '$f_1 = \dfrac{1.875^2}{2\pi \times 9.0} \times 266.5 = 0.0622 \times 266.5 \approx 16.6$ Hz.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm2-problems', 'm2-p3', 2, 'numeric', 2, 'The same 3.0 m aluminium tube, treated as a fixed-free rod in axial motion. Find the first axial frequency.', '$f_n = \dfrac{2n-1}{4L}\sqrt{E/\rho}$.', 'Speed of sound $c = \sqrt{E/\rho} = \sqrt{70\times10^9 / 2700} = 5092$ m/s.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm2-problems', 'm2-p4', 3, 'numeric', 1, 'A uniform cantilever beam is cut to half its length. By what factor does its first bending frequency change?', 'Bending frequency scales as $1/L^2$.', '$f \propto 1/L^2$, so halving $L$ multiplies $f$ by $(1/0.5)^2 = 4$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm2-problems', 'm2-p5', 4, 'numeric', 2, 'The first three axial modes of a stack have effective modal masses of 62%, 21% and 9% of the total. What cumulative percentage do they capture? (The 90% rule applies.)', NULL, '$62 + 21 + 9 = 92\%$. That meets the ≥ 90% guideline, so three modes are enough for this direction.', NULL, NULL, 92, 0.01, '%');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm2-problems', 'm2-p6', 5, 'written', 2, 'Why is a launch vehicle in flight modelled as free-free, while a shaker-table test article is closer to a cantilever or fixed base? What goes wrong if you compare their frequencies directly?', NULL, 'In flight nothing holds the vehicle; it floats and flexes about its centre of mass, so the end conditions are free. On a shaker the base is driven and constrained, so the same structure has different mode shapes and generally lower frequencies.
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('structures-vibration-dynamic-environments', 'm3-problems', 'm3', 'Transients and pogo', 'Dynamic load factors, feed-line frequency and spotting pogo in data.', 'problems', 2);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm3-problems', 'm3-p1', 0, 'numeric', 1, 'A 500 N force is applied as an instant step to an undamped SDOF system with $k = 250$ kN/m. What is the peak displacement, in mm?', 'A step gives a dynamic load factor of 2.', 'Static deflection $= F/k = 500/250000 = 2$ mm.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm3-problems', 'm3-p2', 1, 'numeric', 3, 'A LOX feed line ($\rho = 1141$ kg/m³) is 3.0 m long with a 40 mm inner diameter. A gas accumulator holds 0.5 L at 8 bar, $\gamma = 1.4$. Find the hydraulic frequency $f_{feed}$.', '$I = \rho L / A$, $C = V/(\gamma p)$, $f = 1/(2\pi\sqrt{IC})$. Use SI units: 0.5 L = $5\times10^{-4}$ m³, 8 bar = $8\times10^{5}$ Pa.', '$A = \pi \times 0.04^2/4 = 1.257\times10^{-3}$ m².
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm3-problems', 'm3-p3', 2, 'numeric', 2, 'You increase the accumulator gas volume by a factor of 4, everything else unchanged. By what factor does $f_{feed}$ change?', '$f \propto 1/\sqrt{C}$ and $C \propto V$.', '$f \propto 1/\sqrt{IC}$ and $C \propto V$, so $f$ scales as $1/\sqrt{4} = 0.5$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm3-problems', 'm3-p4', 3, 'numeric', 2, 'The feed line is replaced by one twice as long (same diameter, same accumulator). By what factor does $f_{feed}$ change?', NULL, '$I \propto L$, so doubling $L$ doubles $I$. Then $f \propto 1/\sqrt{I}$ falls by $1/\sqrt{2} = 0.707$.', NULL, NULL, 0.707, 0.02, '×');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm3-problems', 'm3-p5', 4, 'written', 3, 'Static-fire data show a growing line at 22 Hz that drifts up to 25 Hz as propellant depletes. A colleague says it is chamber combustion instability. What evidence would you gather to decide, and what is your first suspicion?', NULL, 'A frequency that tracks the structure''s axial mode as mass changes points to **pogo**, because the line is following the structure rather than a fixed feed-system or chamber resonance.
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4', 'Spectra, margins and test levels', 'Grms, dB slopes, Miles'' equation and margin of safety.', 'problems', 3);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4-p1', 0, 'numeric', 1, 'A flat PSD of 0.04 g²/Hz extends from 50 Hz to 800 Hz. What is the overall Grms of that band?', 'Area $= $ height × width, then take the square root.', 'Area $= 0.04 \times (800 - 50) = 30$ g².
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4-p2', 1, 'numeric', 2, 'A part with $f_n = 100$ Hz and $Q = 10$ sits where the input PSD is 0.04 g²/Hz. Estimate its response with Miles'' equation.', '$G_{rms} \approx \sqrt{\frac{\pi}{2} f_n Q \,\mathrm{PSD}(f_n)}$.', '$\frac{\pi}{2} \times 100 \times 10 \times 0.04 = 62.83$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4-p3', 2, 'numeric', 1, 'A predicted flight level is 4.0 Grms. What Grms is the **qualification** level at +6 dB?', '+6 dB on a PSD is ×4, so Grms scales by the square root.', '+6 dB on the PSD multiplies it by about 4, so Grms is multiplied by $\sqrt{4} = 2$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4-p4', 3, 'numeric', 1, 'A PSD plateau of 0.02 g²/Hz gets a +3 dB margin. What is the new plateau level (g²/Hz)?', NULL, '+3 dB is a factor of $10^{0.3} = 1.995 \approx 2$ in power.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4-p5', 4, 'numeric', 3, 'A PSD rises from 0.01 g²/Hz at 20 Hz to 0.04 g²/Hz at 50 Hz. What is the slope in dB per octave?', 'dB/oct $= 10\log_{10}(W_2/W_1) / \log_2(f_2/f_1)$.', '$10\log_{10}(0.04/0.01) = 10\log_{10}4 = 6.02$ dB.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4-p6', 5, 'numeric', 2, 'A joint has an allowable load of 30 kN. The limit load is 18 kN and the factor of safety is 1.4. What is the margin of safety?', '$\mathrm{MS} = \dfrac{\text{allowable}}{\mathrm{FoS} \times \text{limit}} - 1$', '$\mathrm{FoS} \times \text{limit} = 1.4 \times 18 = 25.2$ kN.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm4-problems', 'm4-p7', 6, 'written', 3, 'Why can''t a shock response spectrum be converted back into a unique time history? Why is it still useful?', NULL, 'An SRS keeps only the **peak** response of each oscillator and discards phase and the timing of when each peak occurs. Many different pulses can produce the same envelope, so the mapping is many-to-one.
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5', 'Measurement chain problems', 'Aliasing, mounting limits, ADC resolution and range planning.', 'problems', 4);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5-p1', 0, 'numeric', 1, 'A 7 kHz tone is sampled at 10 kS/s with no anti-alias filter. At what frequency does it appear?', '$f_{alias} = |f - k f_s|$ with $k$ the nearest integer to $f/f_s$.', '$f/f_s = 0.7$, nearest integer $k = 1$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5-p2', 1, 'numeric', 1, 'You need a 10 kHz vibration bandwidth behind a practical analogue anti-alias filter. What is the minimum sample rate using the usual 2.56 factor, in Hz?', NULL, '$2.56 \times 10\,000 = 25\,600$ Hz (25.6 kS/s). The extra margin over Nyquist gives the filter room to roll off.', NULL, NULL, 25600, 0.01, 'Hz');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5-p3', 2, 'numeric', 2, 'An accelerometer''s mounted resonance is 8 kHz. Up to what frequency can you trust it to about +4%?', 'The usable band is about one fifth of the mounted resonance.', 'At $r = 1/5$ the error is $1/(1 - 0.04) - 1 = 4.2\%$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5-p4', 3, 'numeric', 2, 'At 2 kHz, a lightly damped accelerometer with a 6 kHz mounted resonance reads high by what percentage?', 'Error $= \dfrac{1}{1 - r^2} - 1$ with $r = f/f_{mounted}$.', '$r = 2000/6000 = 1/3$.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5-p5', 4, 'numeric', 2, 'A 16-bit ADC covers ±5 V. The accelerometer is 10 mV/g. What acceleration does one ADC step represent, in mg?', 'One step $= 10\ \mathrm{V} / 2^{16}$. Divide by the sensitivity.', 'Step $= 10 / 65536 = 1.526\times10^{-4}$ V $= 0.1526$ mV.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5-p6', 5, 'numeric', 2, 'With the 10 mV/g sensor and ±5 V ADC, an expected peak of 120 g uses what percentage of the ADC range?', NULL, '$120 \times 10\ \mathrm{mV} = 1.2$ V.
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('structures-vibration-dynamic-environments', 'm5-problems', 'm5-p7', 6, 'written', 3, 'You must measure a separation shock on a stage. Choose a sensor type, bandwidth, sample rate and mounting approach, and justify each choice.', NULL, '**Sensor:** piezoresistive or a shock-rated piezoelectric (charge-mode or IEPE with high-g rating), because the peak can be thousands of g and a normal sensor can clip or zero-shift.
